<?php
/** DevDeployments - from DevDeployments.dc.html (dark). History: git reflog / git log of this checkout (read-only, cdp_devDeployments + sl_devGit), change log cdb_dev_changelog, migration ledger. No deploy or rollback buttons: deploying is done outside the app. */
if (!isset($d)) { $d = []; }
$git = $d['git'];
?>
<div class="sl-head"><div><h1 class="sl-title">Deployments</h1><p class="sl-lede">What is running on this checkout, how it got there, and the change log</p></div><div class="row g8 wrap"><span class="live"><span class="ld"></span><?= $git['available'] ? h($git['branch'] . ' @ ' . $git['head']) : h($git['source']) ?></span><?php if ($git['dirty']): ?><span class="sl-pill pending"><?= (int) $git['dirty'] ?> uncommitted files</span><?php endif; ?><span class="chipbtn">Version <?= h($d['version'] ?: '—') ?></span></div></div>
<section class="sl-card col g16"><div class="sl-ch" style="margin:0"><div><h2 class="sl-ct">Pipeline for the running version</h2><div class="mut sm">Code → tests → dependencies → deploy → health check</div></div></div><div class="row" style="align-items:flex-start"><?php foreach ((array) sl_get($d, 'steps', []) as $s): ?><div class="stp <?= sl_v($s, 'cls') ?>"><span class="dot"><i class="ic ic-sm <?= sl_v($s, 'icon') ?>" aria-hidden="true"></i></span><b class="fw5"><?= sl_v($s, 'label') ?></b><span class="mut sm"><?= sl_v($s, 'sub') ?></span></div><?php endforeach; ?></div></section>
<div class="grid cols4"><?php foreach ((array) sl_get($d, 'kpis', []) as $k): ?><div class="ik"><div class="t"><?= sl_v($k, 'label') ?></div><div class="v"><?= sl_v($k, 'v') ?><small><?= sl_v($k, 'unit') ?></small></div><div class="sm <?= sl_v($k, 'dc') ?>"><?= sl_v($k, 'd') ?></div></div><?php endforeach; ?></div>
<div class="split"><section class="a sl-card flush"><div class="row between wrap g8" style="padding:14px 16px"><div><h2 class="sl-ct">Deployment tracker</h2><div class="mut sm"><?= count($d['deps']) ?> entries from the git reflog</div></div></div><div class="tl"><div class="tlr mut sm" style="border-top:0;padding-top:0"><span></span><span>Commit</span><span>Change</span><span>By</span><span>Status</span><span>When</span></div><?php foreach ((array) sl_get($d, 'deps', []) as $it_d): ?><div class="tlr"><span class="dt <?= sl_v($it_d, 'dc') ?>"></span><span class="col"><b class="fw5 mono"><?= sl_v($it_d, 'ver') ?></b><span class="mono sm mut">from <?= sl_v($it_d, 'sha') ?></span></span><span class="col"><span><?= sl_v($it_d, 'msg') ?></span><span class="mut sm"><?= sl_v($it_d, 'dur') ?></span></span><span class="row g6 sm"><span class="sl-av sm"><?= sl_v($it_d, 'ini') ?></span><?= sl_v($it_d, 'by') ?></span><span class="col g4"><span class="sl-pill <?= sl_v($it_d, 'pc') ?>" style="align-self:flex-start"><?= sl_v($it_d, 'status') ?></span></span><span class="mut sm"><?= sl_v($it_d, 'when') ?></span></div><?php endforeach; ?><?php if (!sl_get($d, 'deps')): ?><div class="sl-empty">No git history: this checkout was not deployed with git.</div><?php endif; ?></div></section>
<aside class="b col g16"><section class="sl-card col g12"><h2 class="sl-ct">Deploy frequency · 14 days</h2><div class="row g6" style="align-items:flex-end;height:110px"><?php foreach ($d['freq'] as $f): ?><div class="grow" title="<?= h($f['l'] . ': ' . $f['n']) ?>" style="height:<?= (int) $f['h'] ?>%;background:var(--green);border-radius:4px 4px 0 0;opacity:<?= $f['n'] ? '1' : '.25' ?>"></div><?php endforeach; ?></div><div class="row between mbf"><span><?= h($d['freq'][0]['l']) ?></span><span><?= h(end($d['freq'])['l']) ?></span></div></section>
<section class="sl-card col g8"><h2 class="sl-ct">Rollbacks</h2><?php foreach (array_slice($d['rollbacks'], 0, 5) as $r): ?><div class="kvr"><span><?= h(($r['from'] ?? '') . ' → ' . $r['hash']) ?></span><span class="mut"><?= h(sl_ago($r['ts'])) ?></span></div><?php endforeach; ?><?php if (!$d['rollbacks']): ?><span class="mut sm">No git reset in the reflog.</span><?php endif; ?></section>
<section class="sl-card col g8"><h2 class="sl-ct">Database migrations</h2><?php foreach ((array) $d['migrations'] as $m): ?><div class="kvr"><span class="mono sm"><?= h($m->name) ?></span><span class="mut"><?= h(sl_date($m->applied_at, 'M j')) ?></span></div><?php endforeach; ?></section></aside></div>
<section class="sl-card col g12"><div class="sl-ch" style="margin:0"><div><h2 class="sl-ct">Change log</h2><div class="mut sm">Every change in every release, newest first. <?= (int) $d['changeCount'] ?> changes.</div></div><div class="row g6 wrap"><?php foreach ((array) sl_get($d, 'kinds', []) as $ty): ?><a class="chipbtn <?= sl_v($ty, 'cls') ?>" style="height:32px" href="<?= sl_v($ty, 'href') ?>"><?= sl_v($ty, 'label') ?></a><?php endforeach; ?><button class="sl-btn sm" data-sl-open="cl-new"><i class="ic ic-sm i-plus" aria-hidden="true"></i>Add entry</button></div></div>
<div class="cl"><?php foreach ((array) sl_get($d, 'log', []) as $v): ?><details class="cv" open><summary class="cvh"><i class="ic ic-sm i-down" aria-hidden="true"></i><b class="fw5"><?= sl_v($v, 'ver') ?></b><span class="sl-pill <?= $v['env'] === 'production' ? 'delivered' : 'onway' ?>"><?= sl_v($v, 'env') ?></span><span class="mut sm"><?= sl_v($v, 'date') ?> · <?= sl_v($v, 'by') ?> · <?= (int) $v['n'] ?> changes</span></summary><?php foreach ((array) sl_get($v, 'items', []) as $c): ?><div class="ce"><span class="ct <?= sl_v($c, 'cls') ?>"><?= sl_v($c, 'type') ?></span><span><?= sl_v($c, 'text') ?></span><span class="mono sm mut"><?= sl_v($c, 'ref') ?></span></div><?php endforeach; ?></details><?php endforeach; ?><?php if (!sl_get($d, 'log')): ?><div class="sl-empty"><?= sl_get($d, 'changelogReady') ? 'No change log entries yet. Add one per release.' : 'Change log table missing: run migrations/2026_11_06_freight_devops.sql.' ?></div><?php endif; ?></div>
<?php if (!empty($d['commits'])): ?><span class="up">Recent commits (git log)</span><div class="term"><?php foreach (array_slice($d['commits'], 0, 15) as $c): ?><div class="ln"><span class="ts"><?= h(date('M j H:i', $c['at'])) ?></span><span class="sv mono"><?= h($c['sha']) ?></span><span class="lv i"><?= h(mb_substr($c['by'], 0, 10)) ?></span><span><?= h($c['msg']) ?></span></div><?php endforeach; ?></div><?php endif; ?></section>
<?php if (sl_get($d, 'changelogReady')): ?><div class="sl-dialog" id="cl-new" hidden><form class="sl-modal" data-sl-form data-sl-reload action="ajax/sl/dev_ajax.php" method="post" role="dialog" aria-label="Add change log entry"><input type="hidden" name="op" value="changelog_add"><h2 class="sl-ct">Add to the change log</h2>
<div class="grid cols2" style="gap:10px"><label class="sl-field"><span class="sl-lab">Version / release</span><input class="sl-in mono" name="version" required value="<?= h($d['version']) ?>"></label><label class="sl-field"><span class="sl-lab">Kind</span><select class="sl-sel native" name="kind"><option value="feature">Feature</option><option value="fix">Fix</option><option value="change" selected>Change</option><option value="security">Security</option><option value="migration">Migration</option></select></label>
<label class="sl-field"><span class="sl-lab">Environment</span><select class="sl-sel native" name="environment"><option>production</option><option>staging</option><option>development</option></select></label><label class="sl-field"><span class="sl-lab">Commit / ticket</span><input class="sl-in mono" name="ref" value="<?= h($git['head']) ?>"></label></div>
<label class="sl-field"><span class="sl-lab">What changed</span><input class="sl-in" name="title" required></label><label class="sl-field"><span class="sl-lab">Details</span><textarea class="sl-in" name="body" rows="3"></textarea></label>
<div class="row g8"><button type="submit" class="sl-btn">Add</button><button type="button" class="sl-btn ghost" data-sl-close>Cancel</button></div></form></div><?php endif; ?>
